import React from 'react';

function App() {
  const data = [
    { month: 'Jan', value: 65 },
    { month: 'Fev', value: 85 },
    { month: 'Mar', value: 45 },
    { month: 'Abr', value: 90 },
    { month: 'Mai', value: 70 },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-200 p-8">
      <div className="max-w-4xl mx-auto bg-white rounded-xl shadow-2xl p-8">
        <h1 className="text-3xl font-bold text-gray-800 mb-8 text-center">
          Vendas Mensais 2024
        </h1>

        {/* Graph container with fixed height and grid lines */}
        <div className="relative h-80 mb-8">
          {/* Background grid lines */}
          <div className="absolute inset-0 grid grid-rows-4 gap-4">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="border-t border-gray-200"></div>
            ))}
          </div>

          {/* Bars container */}
          <div className="relative h-full flex items-end justify-between px-4">
            {data.map((item, index) => (
              <div key={index} className="flex flex-col items-center group">
                {/* Value tooltip */}
                <div className="absolute -top-8 opacity-0 group-hover:opacity-100 transition-opacity">
                  <span className="bg-gray-800 text-white px-2 py-1 rounded text-sm">
                    {item.value}%
                  </span>
                </div>

                {/* Bar */}
                <div 
                  style={{ height: `${item.value}%` }}
                  className="w-16 bg-gradient-to-t from-blue-600 to-blue-400 
                           rounded-t-lg transition-all duration-300 
                           hover:from-blue-700 hover:to-blue-500"
                ></div>

                {/* Month label */}
                <span className="mt-2 text-sm font-medium text-gray-700">
                  {item.month}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Stats cards */}
        <div className="mt-6 grid grid-cols-3 gap-6">
          <div className="bg-blue-50 p-6 rounded-xl shadow-md">
            <h3 className="text-lg font-semibold text-gray-700">Média</h3>
            <p className="text-3xl font-bold text-blue-600">71%</p>
          </div>
          <div className="bg-green-50 p-6 rounded-xl shadow-md">
            <h3 className="text-lg font-semibold text-gray-700">Máximo</h3>
            <p className="text-3xl font-bold text-green-600">90%</p>
          </div>
          <div className="bg-red-50 p-6 rounded-xl shadow-md">
            <h3 className="text-lg font-semibold text-gray-700">Mínimo</h3>
            <p className="text-3xl font-bold text-red-600">45%</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
